pragma solidity ^0.8.26;

contract TownCrier {
    struct Request {
        address requester;
        uint fee;
        address callbackAddr;
        bytes4 callbackFID;
        bytes32 paramsHash;
    }

    event Upgrade(address newAddr);
    event Reset(uint gas_price, uint min_fee, uint cancellation_fee); 
    event RequestInfo(uint64 id, uint8 requestType, address requester, uint fee, address callbackAddr, bytes32 paramsHash, uint timestamp, bytes32[] requestData);
    event DeliverInfo(uint64 requestId, uint fee, uint gasPrice, uint gasLeft, uint callbackGas, bytes32 paramsHash, uint64 error, bytes32 respData);
    event Cancel(uint64 requestId, address canceller, address requester, uint fee, int flag);

    address public constant SGX_ADDRESS = 0x18513702cCd928F2A3eb63d900aDf03c9cc81593;

    uint public GAS_PRICE = 5 * 10**10;
    uint public MIN_FEE = 30000 * GAS_PRICE;
    uint public CANCELLATION_FEE = 25000 * GAS_PRICE;

    uint public constant CANCELLED_FEE_FLAG = 1;
    uint public constant DELIVERED_FEE_FLAG = 0;
    int public constant FAIL_FLAG = -2 ** 250;
    int public constant SUCCESS_FLAG = 1;

    bool public killswitch;

    bool public externalCallFlag;

    uint64 public requestCnt;
    uint64 public unrespondedCnt;
    Request[2**64] public requests;

    int public newVersion = 0;

    receive() external payable {}

    constructor() {
        requestCnt = 1;
        requests[0].requester = msg.sender;
        killswitch = false;
        unrespondedCnt = 0;
        externalCallFlag = false;
    }

    function upgrade(address newAddr) public {
        if (msg.sender == requests[0].requester && unrespondedCnt == 0) {
            unchecked {
                newVersion = -int(int160(uint160(newAddr)));
            }
            killswitch = true;
            emit Upgrade(newAddr);
        }
    }

    function reset(uint price, uint minGas, uint cancellationGas) public {
        if (msg.sender == requests[0].requester && unrespondedCnt == 0) {
            GAS_PRICE = price;
            unchecked {
                MIN_FEE = price * minGas;
                CANCELLATION_FEE = price * cancellationGas;
            }
            emit Reset(GAS_PRICE, MIN_FEE, CANCELLATION_FEE);
        }
    }

    function suspend() public {
        if (msg.sender == requests[0].requester) {
            killswitch = true;
        }
    }

    function restart() public {
        if (msg.sender == requests[0].requester && newVersion == 0) {
            killswitch = false;
        }
    }

    function withdraw() public {
        if (msg.sender == requests[0].requester && unrespondedCnt == 0) {
            (bool success, ) = payable(requests[0].requester).call{value: address(this).balance}("");
            if (!success) {
                revert();
            }
        }
    }

    function request(uint8 requestType, address callbackAddr, bytes4 callbackFID, uint timestamp, bytes32[] memory requestData) public payable returns (int) {
        if (externalCallFlag) {
            revert();
        }

        if (killswitch) {
            externalCallFlag = true;
            (bool success, ) = payable(msg.sender).call{value: msg.value}("");
            if (!success) {
                revert();
            }
            externalCallFlag = false;
            return newVersion;
        }

        if (msg.value < MIN_FEE) {
            externalCallFlag = true;
            (bool success, ) = payable(msg.sender).call{value: msg.value}("");
            if (!success) {
                revert();
            }
            externalCallFlag = false;
            return FAIL_FLAG;
        } else {
            uint64 requestId = requestCnt;
            unchecked {
                requestCnt++;
                unrespondedCnt++;
            }

            bytes32 paramsHash = keccak256(abi.encodePacked(requestType, requestData));
            requests[requestId].requester = msg.sender;
            requests[requestId].fee = msg.value;
            requests[requestId].callbackAddr = callbackAddr;
            requests[requestId].callbackFID = callbackFID;
            requests[requestId].paramsHash = paramsHash;

            emit RequestInfo(requestId, requestType, msg.sender, msg.value, callbackAddr, paramsHash, timestamp, requestData);
            return int(uint256(requestId));
        }
    }

    function deliver(uint64 requestId, bytes32 paramsHash, uint64 error, bytes32 respData) public {
        if (msg.sender != SGX_ADDRESS ||
                requestId <= 0 ||
                requests[requestId].requester == address(0) ||
                requests[requestId].fee == DELIVERED_FEE_FLAG) {
            return;
        }

        uint fee = requests[requestId].fee;
        if (requests[requestId].paramsHash != paramsHash) {
            return;
        } else if (fee == CANCELLED_FEE_FLAG) {
            payable(SGX_ADDRESS).send(CANCELLATION_FEE);
            requests[requestId].fee = DELIVERED_FEE_FLAG;
            unchecked {
                unrespondedCnt--;
            }
            return;
        }

        requests[requestId].fee = DELIVERED_FEE_FLAG;
        unchecked {
            unrespondedCnt--;
        }

        if (error < 2) {
            payable(SGX_ADDRESS).send(fee);         
        } else {
            externalCallFlag = true;
            (bool success, ) = payable(requests[requestId].requester).call{value: fee, gas: 2300}("");
            externalCallFlag = false;
        }

        uint callbackGas;
        unchecked {
            callbackGas = (fee - MIN_FEE) / tx.gasprice;
        }
        emit DeliverInfo(requestId, fee, tx.gasprice, gasleft(), callbackGas, paramsHash, error, respData);
        if (callbackGas > gasleft() - 5000) {
            unchecked {
                callbackGas = gasleft() - 5000;
            }
        }

        externalCallFlag = true;
        (bool success, ) = payable(requests[requestId].callbackAddr).call{gas: callbackGas}(abi.encodeWithSelector(requests[requestId].callbackFID, requestId, error, respData));
        externalCallFlag = false;
    }

    function cancel(uint64 requestId) public returns (int) {
        if (externalCallFlag) {
            revert();
        }

        if (killswitch) {
            return 0;
        }

        uint fee = requests[requestId].fee;
        if (requests[requestId].requester == msg.sender && fee >= CANCELLATION_FEE) {
            requests[requestId].fee = CANCELLED_FEE_FLAG;
            externalCallFlag = true;
            (bool success, ) = payable(msg.sender).call{value: fee - CANCELLATION_FEE}("");
            if (!success) {
                revert();
            }
            externalCallFlag = false;
            emit Cancel(requestId, msg.sender, requests[requestId].requester, requests[requestId].fee, 1);
            return SUCCESS_FLAG;
        } else {
            emit Cancel(requestId, msg.sender, requests[requestId].requester, fee, -1);
            return FAIL_FLAG;
        }
    }
}

