    uint private balance = 0;
    uint private fee = 5;
    uint private multiplier = 125;

    mapping (address => User) private users;
    Entry[] private entries;
    uint[] private unpaidEntries;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyowner() { if (msg.sender == owner) _; }

    struct User {
        address id;
        uint deposits;
        uint payoutsReceived;
    }

    struct Entry {
        address entryAddress;
        uint deposit;
        uint payout;
        bool paid;
    }

    receive() external payable {
        init();
    }

    function init() private {
        if (msg.value < 1 ether) {
            payable(msg.sender).send(msg.value);
            return;
        }

        join();
    }

    function join() private {
        uint dValue = 1 ether;

        if (msg.value > 1 ether) {
            payable(msg.sender).send(msg.value - 1 ether);
            dValue = 1 ether;
        }

        if (users[msg.sender].id == address(0)) {
            users[msg.sender].id = msg.sender;
            users[msg.sender].deposits = 0;
            users[msg.sender].payoutsReceived = 0;
        }

        entries.push(Entry(msg.sender, dValue, (dValue * multiplier) / 100, false));
        users[msg.sender].deposits++;
        unpaidEntries.push(entries.length - 1);

        unchecked {
            balance += (dValue * (100 - fee)) / 100;
        }

        uint index = unpaidEntries.length > 1 ? rand(unpaidEntries.length) : 0;
        Entry storage theEntry = entries[unpaidEntries[index]];

        if (balance > theEntry.payout) {
            uint payout = theEntry.payout;

            payable(theEntry.entryAddress).send(payout);
            theEntry.paid = true;
            users[theEntry.entryAddress].payoutsReceived++;

            unchecked {
                balance -= payout;
            }

            if (index < unpaidEntries.length - 1) {
                unpaidEntries[index] = unpaidEntries[unpaidEntries.length - 1];
            }

            unpaidEntries.pop();

        }

        uint fees = address(this).balance - balance;
        if (fees > 0) {
            payable(owner).send(fees);
        }
    }

    uint256 constant private FACTOR = 1157920892373161954235709850086879078532699846656405640394575840079131296399;

    function rand(uint max) private view returns (uint256 result) {
        uint256 factor = FACTOR * 100 / max;
        uint256 lastBlockNumber = block.number - 1;
        uint256 hashVal = uint256(blockhash(lastBlockNumber));

        unchecked {
            return uint256((uint256(hashVal) / factor)) % max;
        }
    }

    function changeOwner(address newOwner) public onlyowner {
        owner = newOwner;
    }

    function changeMultiplier(uint multi) public onlyowner {
        if (multi < 110 || multi > 150) revert();
        multiplier = multi;
    }

    function changeFee(uint newFee) public onlyowner {
        if (fee > 5) revert();
